    const expected: [1]Triplet = .{
        Triplet.init(27, 36, 45),
    };
    const actual = try tripletsWithSum(testing.allocator, 108);
    defer testing.allocator.free(actual);
    try testing.expectEqualSlices(Triplet, &expected, actual);
